diff --git a/flutter_app/lib/apps/js_app_view.dart b/flutter_app/lib/apps/js_app_view.dart
index dddbdb3d91..b43e01e493 100644
--- a/flutter_app/lib/apps/js_app_view.dart
+++ b/flutter_app/lib/apps/js_app_view.dart
@@ -300,13 +300,21 @@ class _JsAppViewState extends State<JsAppView> {
     await _restart();
   }

+  /// Generation of the latest [_restart] call. Overlapping restarts (reload
+  /// button + fs-revision debounce + dialog paths) used to each boot an
+  /// engine and the last writer won, leaking the others' workers/timers
+  /// while the shared lifecycle chain kept the spinner up. A superseded
+  /// run now bails out and disposes whatever it already built.
+  int _restartGen = 0;
+
   Future<void> _restart() async {
+    final gen = ++_restartGen;
     // Yield one microtask: on the first call (from initState) this lets
     // didChangeDependencies run first and record _themeJson, so the engine
     // boots with the real theme instead of an empty map. A microtask (not
     // Future(...)/Timer) keeps widget tests' fake-async zone clean.
     await Future<void>.value();
-    if (!mounted) return;
+    if (!mounted || gen != _restartGen) return;
     final themeJson = _themeJson;
     final initialTheme = themeJson == null
         ? jsThemeMap(context)
@@ -317,6 +325,7 @@ class _JsAppViewState extends State<JsAppView> {
       _startError = null;
     });
     if (old != null) await old.dispose();
+    if (!mounted || gen != _restartGen) return;
     try {
       final effective = widget.permissionsStore.forApp(widget.app).effective();
       final engine = JsAppEngine(
@@ -340,7 +349,7 @@ class _JsAppViewState extends State<JsAppView> {
       );
       engine.onCloseRequested = _closeFromJs;
       await engine.start();
-      if (!mounted) {
+      if (!mounted || gen != _restartGen) {
         await engine.dispose();
         return;
       }
@@ -350,7 +359,7 @@ class _JsAppViewState extends State<JsAppView> {
       _appSignature = await _readAppSignature();
     } on Object catch (error) {
       AppLog.i('apps', 'app start failed: ${widget.app.id} — $error');
-      if (mounted) setState(() => _startError = error);
+      if (mounted && gen == _restartGen) setState(() => _startError = error);
     }
   }

diff --git a/flutter_app/test/apps/js_app_chrome_test.dart b/flutter_app/test/apps/js_app_chrome_test.dart
index 16a138598e..41a90b6f87 100644
--- a/flutter_app/test/apps/js_app_chrome_test.dart
+++ b/flutter_app/test/apps/js_app_chrome_test.dart
@@ -225,5 +225,41 @@ void main() {
       });
       await tester.pump();
     });
+
+    testWidgets('overlapping reloads settle on one rendered app', (
+      tester,
+    ) async {
+      final env = await brokenAppEnv();
+      await pumpView(
+        tester,
+        env,
+        manifest: const {'id': 'demo', 'name': 'Demo', 'chrome': 'full'},
+      );
+      await tester.runAsync(() async {
+        await env.writeFile('apps/demo/widget.js', widgetJs);
+        // Two reload taps back to back: the superseded restart must bail out
+        // (and dispose what it built) instead of racing the newer one.
+        for (var i = 0; i < 2; i++) {
+          await tester.tap(find.byIcon(Icons.more_vert));
+          await tester.pump();
+          await tester.pump(const Duration(seconds: 1));
+          await tester.tap(find.text('Reload app'));
+          await tester.pump();
+        }
+        for (var i = 0; i < 30; i++) {
+          await Future<void>.delayed(const Duration(milliseconds: 100));
+          await tester.pump();
+          if (find.text('reloaded').evaluate().isNotEmpty) break;
+        }
+      });
+      expect(find.text('reloaded'), findsOneWidget);
+      // AC2: the spinner must settle once the winning engine renders — no
+      // stuck progress indicator from the superseded restart chain.
+      expect(find.byType(CircularProgressIndicator), findsNothing);
+      await tester.runAsync(() async {
+        await tester.pumpWidget(const SizedBox.shrink());
+        await Future<void>.delayed(const Duration(milliseconds: 100));
+      });
+    });
   }, skip: _engineSkip);
 }

